float g_glow = 0.;

float smin( float a, float b, float k )
{
    k *= 1.0;
    float r = exp2(-a/k) + exp2(-b/k);
    return -k*log2(r);
}

float sdSegment_glow( in vec2 p, in vec2 a, in vec2 b )
{
    vec2 pa = p-a, ba = b-a;
    float h = clamp( dot(pa,ba)/dot(ba,ba), 0.0, 1.0 );
    float d = length( pa - ba*h );
    g_glow += 1./(1.+15.*d*d);
    return d;
}

float sdBezier_glow( in vec2 pos, in vec2 A, in vec2 B, in vec2 C )
{    
    vec2 a = B - A;
    vec2 b = A - 2.0*B + C;
    vec2 c = a * 2.0;
    vec2 d = A - pos;
    float kk = 1.0/dot(b,b);
    float kx = kk * dot(a,b);
    float ky = kk * (2.0*dot(a,a)+dot(d,b)) / 3.0;
    float kz = kk * dot(d,a);      
    float res = 0.0;
    float p = ky - kx*kx;
    float p3 = p*p*p;
    float q = kx*(2.0*kx*kx-3.0*ky) + kz;
    float h = q*q + 4.0*p3;
    if( h >= 0.0) 
    { 
        h = sqrt(h);
        vec2 x = (vec2(h,-h)-q)/2.0;
        vec2 uv = sign(x)*pow(abs(x), vec2(1.0/3.0));
        float t = clamp( uv.x+uv.y-kx, 0.0, 1.0 );
        res = dot2(d + (c + b*t)*t);
    }
    else
    {
        float z = sqrt(-p);
        float v = acos( q/(p*z*2.0) ) / 3.0;
        float m = cos(v);
        float n = sin(v)*1.732050808;
        vec3  t = clamp(vec3(m+m,-n-m,n-m)*z-kx,0.0,1.0);
        res = min( dot2(d+(c+b*t.x)*t.x),
                   dot2(d+(c+b*t.y)*t.y) );
        // the third root cannot be the closest
        // res = min(res,dot2(d+(c+b*t.z)*t.z));
    }
    res= sqrt(res);
    g_glow += 1./(1.+15.*res*res);
    return res;
}

float sdBi(vec2 p)
{
    float d= sdSegment_glow(p, vec2(-1,.2), vec2(-1,.8));
    d = min(d, sdSegment_glow(p, vec2(-1,.8), vec2(1, .8)));
    d = min(d, sdBezier_glow(p, vec2(1, .8), vec2(1, -1) ,vec2(-.7, -1)));
    d = min(d, sdSegment_glow(p, vec2(0, .8), vec2(0, 1)));

    return d;
}

float sdI(vec2 p)
{
    float d = sdSegment_glow(p, vec2(-1, 1), vec2(-1, -1));
    d = min(d, sdSegment_glow(p, vec2(-1,-1), vec2(1, -1)));
    d = min(d, sdBezier_glow(p, vec2(-1, .3), vec2(0, .33), vec2(.9, .5)));
    d = min(d, sdSegment_glow(p, vec2(.64, .66), vec2(.6, .82)));
    d = min(d, sdSegment_glow(p, vec2(.94, .7), vec2(.9, .85)));
    return d;
}

float sdYu(vec2 p)
{
    float d = sdSegment_glow(p, vec2(-.8, .8), vec2(.5,.8));
    d = min(d, sdSegment_glow(p, vec2(.5,.8), vec2(.3, -.9)));
    d = min(d, sdSegment_glow(p, vec2(-1, -.9), vec2(1, -.9)));

    return d;

}

float sdKyu(vec2 p)
{
    float d = sdSegment_glow(p, vec2(0,1),vec2(0.1,-1));
    d = min(d, sdSegment_glow(p, vec2(-.8, .55), vec2(.8, .6)));
    d = min(d, sdSegment_glow(p, vec2(-1, -.3), vec2(1, -.2)));

    return d;
}

#undef ag

float sdKyuubi(vec2 p)
{
    float gwidth = 2.3;
    p.x += 1.5*gwidth;
    float d = sdKyu(p);
    p.x -= gwidth;
    d = min(d, sdYu(p*1.3-vec2(0,-.3)));
    p.x -= gwidth;
    d = min(d, sdBi(p*1.21));
    p.x -= gwidth;
    d = min(d, sdI(p*1.23));

    return d;
}

