void eye1(vec2 fragCoord, vec2 uv, inout vec4 o)
{
    uv *= 1.05;
    float s = 1.+.3*smoothstep(0.0, 0.1, uv.x);
    vec2 buv = uv;
    uv *= rot(.1);
    uv.x = s*abs(uv.x);
    uv *= rot(.1);
    float what = .5 + .5*sin(iTime);
    float sde = sdParallelogram(uv, .05,.01,.02)-.01;
    //sde = sdParallelogram(uv, .07,.02,.02);
    o = mix(o, vec4(1), smoothstep(0.001,0.,sde));
    float ineye = sde;
    //eyelashes
    uv = buv;
    //sde = sdSegment(uv, vec2(-.13, 0), vec2(.04));
    sde = sdBezier(uv,  vec2(-.13, 0.01), vec2(-.04,.01), vec2(.06,.04));
    o = mix(o, vec4(0), smoothstep(0.01,0.00,abs(sde)));
    //eyebrows
    uv.y += .0;
    sde = sdBezier(uv, vec2(-.08, .03), vec2(-0.03, .04), vec2(.01, .07));
    o = mix(o, vec4(.1), smoothstep(0.009,.003,abs(sde)));
    //pupils n such
    uv = buv;
    uv.y -= .015;
    uv.x -= .006;
    //iris
    sde = length(uv)-.034;
    float sde2 = max(sde, ineye);
    sde = max(-sde, ineye);
    vec2 tuv = fragCoord/iResolution.xy;
    tuv -= .49;
    tuv.x -= .5*uv.x;
    tuv *= rot(.1);
    tuv = tri(tuv * 5.);

    vec4 last = 1.5*vec4(.5,.5,1,1)*(.5+.5*noise(255.*uv));
    o = mix(o, last, smoothstep(0.004,0.00, sde2));
    float ow = .007;
    o = mix(o, vec4(0), smoothstep(ow,0.,abs(sde)));

    sde = length(uv)-.017;
    sde = max(sde, ineye);
    o = mix(o, vec4(0), smoothstep(0.004,.00,sde));
}

