void eye3(vec2 fragCoord, vec2 uv, inout vec4 o)
{
    vec2 buv = uv;
    uv *= .7;
    uv.x += .01;
    uv *= rot(.2);
    float sde = sdBox(uv-vec2(.024,0), vec2(.025,.012));
    uv.x += .02;
    uv.x *= .5;
    uv *= rot(PI/2.-.25);
    uv.x -= .003;
    //eyelashes outline
    float amt = smoothstep(0.0,0.006, -buv.x+.056);
    // upper line thicker than lower
    sde = smin(sde, sdEquilateralTriangle(uv, .011),0.001);
    o = mix(o, vec4(0.1), amt*smoothstep(.009,0.004,sde));
    o = mix(o, vec4(1), smoothstep(0.002,0.,sde));
    float ineye = sde;


    //eyebrows
    uv = buv;
    uv.y -= .02;
    sde = sdBezier(uv, vec2(-.08, .03), vec2(-0.03, .04), vec2(.01, .07));
    o = mix(o, vec4(.2), smoothstep(0.005,.003,abs(sde)));
    //pupils n such
    uv = buv;
    uv.y -= 0.02;
    //iris
    sde = length(uv)-.034;
    float sde2 = max(sde, ineye);
    sde = max(-sde, ineye);
    vec2 tuv = fragCoord/iResolution.xy;
    tuv -= .5;
    tuv.x -= .5*uv.x;
    tuv *= rot(.1*iTime);
    tuv = tri(tuv * 23.);

    vec4 last = texture(iChannel1, tuv);
    last.rgb = 3.*vec3(.5,.5,1)*hue_shift(last.rgb, .5);
    o = mix(o, last, smoothstep(0.004,0.00, sde2));
    float ow = .007;

    sde = length(uv)-.02;
    sde = max(sde, ineye);
    o = mix(o, vec4(0), smoothstep(0.004,.00,sde));
}

void mouth(vec2 fragCoord, vec2 uv, inout vec4 o)
{
    uv *= .9;
    uv.y -= .02;
    float sde = sdBezier(uv, vec2(-.034, -.17), vec2(0,-.17), vec2(.04,-.164));

    uv.y = -uv.y;
    uv -= vec2(-.02, .177);
    uv *= rot(-.1);
    float m = sdEquilateralTriangle(uv, .011);

    o = mix(o, vec4(1), smoothstep(0.004,0.00,m));
    o = mix(o, vec4(.6), smoothstep(0.002,0.0,abs(m)));
    float w = .003+.0016*smoothstep(0.03,0.0, uv.x-.01);
    o = mix(o, vec4(0), smoothstep(w,w-.003,abs(sde)));
}

float sdEquilateralTriangle_nobot( in vec2 p, in float r )
{
    // probably illegal but whatever
    if(p.y > 0.)
    {
        const float k = sqrt(3.0);
        p.x = abs(p.x) - r;
        p.y = p.y + r/k;
        if( p.x+k*p.y>0.0 ) p = vec2(p.x-k*p.y,-k*p.x-p.y)/2.0;
        p.x -= clamp( p.x, -2.0*r, 0.0 );
        return -length(p)*sign(p.y);
    }
        return 1.;
}

void hair(vec2 fragCoord, vec2 uv, inout vec4 o, inout float headd)
{
    uv = vec2(.9,.8)*(uv-vec2(0,-0.03));
    vec2 buv = uv;
    vec4 haircol = vec4(.12,.12,.13,.4);
    float tt = 0.;//iTime;
    // front layer
    uv.y -=.03;
    uv.y *= .74;
    uv.x += .03*sin(20.*uv.y);
    uv.y -= .06;
    uv.y = -uv.y + step(0.01,uv.y);
    float sdh = sdEquilateralTriangle(uv, .1);
    uv += vec2(.07,-0.02);
    uv *= 1.5;
    uv.x *= 1.8;
    sdh = smin(sdh, sdEquilateralTriangle(uv, .1), 0.002);
    uv.x -= .44 + sin(-uv.y);
    uv.y += .08;
    uv *= .9;
    sdh = smin(sdh, sdEquilateralTriangle(uv, .16), 0.001);
    uv = buv;
    uv.y *= -1.;
    uv.x *= 2.6;
    uv -= vec2(-0.33,-.08);
    sdh = smin(sdh, sdEquilateralTriangle_nobot(uv, .1), 0.001);
    uv = buv;
    uv.y *= -1.;
    uv.x = abs(uv.x);
    uv.y += .09;
    uv *= rot(.5);
    uv.x *= 3.2;
    uv.x -= .6;
    uv.x += .1*sin(18.*uv.y+3.3);
    uv.y += .01;
    sdh = min(sdh, sdEquilateralTriangle_nobot(uv, .1));
    uv *= rot(-1.);
    uv.x -= .01;
    uv.y -= .03;
    sdh = min(sdh, sdEquilateralTriangle_nobot(uv, .1));
    uv = buv;


    uv += .01*sin(uv.yx*33.+1.);
    uv.x = abs(uv.x);

    vec2 u1 = uv;
    uv.x -= .16;
    uv *= rot(-.8);
    uv.x *= 2.;
    sdh = min(sdh, sdEquilateralTriangle_nobot(uv, .1));
    uv = u1;
    uv.x -= .18;
    uv.y -= .05;
    uv.x *= 2.;
    uv *= rot(-.3);
    sdh = min(sdh, sdEquilateralTriangle_nobot(uv, .1));
    uv = u1;
    uv.y += .2*buv.x;
    uv.x -= .08;
    uv.y -= .1;
    uv.x *= 2.;
    uv *= rot(-.5 + 3.*buv.x);
    sdh = min(sdh, sdEquilateralTriangle_nobot(uv, .1));
    uv = u1;
    uv.y += .1*buv.x;
    uv.x -= .02;
    uv.y -= .15;
    uv.x *= 4.;
    uv *= rot(-.2);
    sdh = min(sdh, sdEquilateralTriangle_nobot(uv, .1));
    uv = buv;
    float sdc = length(uv)-.2;
    sdc = max(sdc, -uv.y);
    sdc = max(sdc, -(length(uv)-.12));
    sdh = smin(sdh, sdc,0.002);
    //sdh = sdc;
    // back layer

    float sdb = sdBox(uv - vec2(0,-.16), vec2(.18,.2));
    uv = buv;
    uv.y -= .1;
    uv += .02*sin(uv.yx*26.+5.*tt);
    uv.x = abs(uv.x);
    uv.x -= .1;
    uv *= rot(-2.3);
    uv.x *= 2.5;
    sdb = min(sdb, sdEquilateralTriangle_nobot(uv, .14));
    float sdbs = sdSegment(uv, vec2(0.1, -0.1), vec2(0.1, .2));
    for(float i = 0.; i < 6.; i++)
    {
        uv.x -= .1;
        uv.y -= .05;
        sdb = min(sdb, sdEquilateralTriangle_nobot(uv, .15));
        sdbs = min(sdbs, sdSegment(uv, vec2(-0., 0.), vec2(0.0, .05)));
    }
    sdb = max(sdb, -(headd-0.006));
    sdbs = max(sdbs, sdb);
    // back layer specular stuff?


    // ears
    uv = buv;
    uv.x = abs(uv.x);
    uv.x -= .05;
    uv *= rot(-.5);
    uv.y *= .3;
    uv.y -= .03;
    uv.y *= 1. + 3.7*uv.y;
    uv.x += .3*uv.y;
    float sde = sdEquilateralTriangle_nobot(uv, .14); //further
    //sdh = min(sdh, sdb);
    o = mix(o, haircol*1.1, smoothstep(0.003, 0., sde));
    uv *= rot(-.2);
    uv.x *= 2.5;
    uv.y *= 1.5;
    uv.x += .15;
    uv.y += .04;
    //closer
    float sdce = sdEquilateralTriangle_nobot(uv, .16);
    sde = max(sde, sdce);
    o = mix(o, haircol, smoothstep(0.01, 0., sde));
    o = mix(o, vec4(.3), smoothstep(0.01, 0., sde+.02));

    //fluff
    sde = 999.;
    for(float i = 0.; i < 18.; i++)
    {
        uv = buv;
        uv.x = abs(uv.x);
        uv *= rot(-.4);
        uv *= 1.+.13*sin(uv.yx*24. + 1.*i);
        uv.x -= 0.03;
        uv.y -= .1+.01*i;
        sde = min(sde, length(uv)-.02);
    }
    sde = max(-sdce, sde);
    o = mix(o, vec4(1), smoothstep(0.01,0.,sde));

    // hair colowing
    // texture maybeee??
    uv = buv;

    o = mix(o, haircol*.5, smoothstep(0.01,0., sdb)); // back layer
    o = mix(o, vec4(1), .06*smoothstep(0.05,0., sdbs)); // back layer specular
    //o = mix(o, vec4(.03), smoothstep(0.008,0.006, sdh-.004)); // front layer outline
    float sdhs = max(sdh, headd);
    o = mix(o, 1.2*(o-.4), smoothstep(0.02,0.00, sdhs)); // front layer// hair shadow?

    o = mix(o, haircol, smoothstep(0.005,0.00, sdh)); // front layer
    //o = mix(o, 1.2*(haircol-.05), smoothstep(0.005,0.00, sdh+.008)); // front layer


    // specular refleckshun on top
    float sds = sdBezier(uv, vec2(-.2,0.15), vec2(0, .03), vec2(.2,0.15));
    sds = max(sds, sdh);
    float w = 0.01+0.0*sin(11.*uv.x+1.5);
    float amt = .1*smoothstep(.2,0.,abs(uv.x));
    uv *= rot(.6);
    o = mix(o, vec4(1), amt*smoothstep(w,w-0.009, sds));

    headd = min(headd, sdb);
    headd = min(headd, sdh);

    //o = mix(o, vec4(0), smoothstep(0.004,0, abs(sdh)));
}

void body(vec2 fragCoord, vec2 uv, inout vec4 o, inout float headd)
{
    vec2 bpos = vec2(0, -.51);
    uv = vec2(.7,.7)*(uv)-bpos;

    vec2 buv = uv;
    // rounded rect for torso


    uv.y += uv.x*uv.x;
    // break up the perfectly even arms?
    uv.x *= 1.+1.5*uv.y - .8*uv.y*(uv.y+1.2);
    float sdt = sdBox(uv, vec2(.14,.19))-.1;
    // turtleneck
    float sdcollar = sdBox(uv-vec2(0,.28), vec2(.06,.05));
    sdt = smin(sdt, sdcollar,.01);

    // bewbs
    uv = buv;
    float sdb;
    if(true)
    {
        uv.x = abs(uv.x)+.01;
        uv.x *= .9;
        sdb = length(uv - vec2(.08,0.1))-0.03;
    } else{
        uv.x = sqrt(uv.x*uv.x+.008)-.03;// abs(uv.x);
        sdb = length(uv - vec2(.1,0.1))-0.01;
    }
    sdt = smin(sdt, sdb, 0.003);

    // arm lines?
    uv *= 1.-.3*smoothstep(0.14,0.,sdb);
    float sda = sdSegment(uv, vec2(.14, -.24), vec2(.14,.21));
    // shadow under bosom and on collar
    /* //atmpt 1
    uv *= rot(PI/2.);
    uv.y += .08;
    uv.x += .04;
    float sds = sdEquilateralTriangle(uv, .1);
    */
    uv.y += .055;
    float sds = sdBox(uv, vec2(.14));
    sds = max(sds, -(sdb-.07));

    //sds = max(sds, -(length(uv*vec2(.9,1)-vec2(0,-.16))-.15)); // tummy
    vec2 buv2 = uv;
    uv.x *= 1.3;
    sds = min(sds, length(uv-vec2(0,.41))-.13);
    uv = buv2;
    vec4 col = mix(vec4(.2), vec4(.16), smoothstep(0.02, -0.01, sds));
    col = mix(col, vec4(.13), smoothstep(0.1, 0., sds+.09));
    // texture???
    col *= 1.+.06*noise(uv*68.+33.);
    col *= 1.+.13*noise(uv*368.+77.);
    //o = mix(o, vec4(.1), smoothstep(0.01, 0., sds));
    col = 1.6*(col-.05); // increase contrast
    col = clamp(col, 0.01, 1.);
    buv2 = buv;


    buv2.y -= .1;
    buv2 *= 1. + 5.*sdb;
    //col *= 1.+.5*smoothstep(0.3, 0., sdKyuubi(buv2*19.)); // add text to sweater
    o = mix(o, vec4(.02), smoothstep(0.01, 0., sdt)); // torso outline
    o = mix(o, col, smoothstep(0.001, 0., sdt));


    float amt = smoothstep(0.0, 0.3, -uv.y+.3);
    o = mix(o, vec4(.06), amt*smoothstep(0.004, 0., sda));
}


void head(vec2 fragCoord, inout vec4 o)
{
    vec2 uv = 1.8*(fragCoord-.5*iResolution.xy)/iResolution.y;
    vec2 buv = uv;
    float sdh = length(uv) - .18; // head
    uv.y *= .97;
    uv-=vec2(0,-.13);

    uv.x *= .49 - .8*uv.y;
    uv.y = clamp(abs(uv.y)-.038,0.,99.);
    uv *= rot(.25*PI);

    // head
    float sdc =  3.*sdBox(uv, vec2(.043,.04))-.025; //chin
    sdh = smin(sdc, sdh, .01);
    float headd = sdh;
    o = mix(o, vec4(255, 227, 199,255)/255. , smoothstep(0.01,0.,sdh));
    uv = buv;
    uv.x = abs(uv.x);
    uv.x -= .08;
    uv.y += .14;
    float sdb = length(uv);
    o = mix(o, vec4(250, 208, 182, 255)/255., smoothstep(0.1,0.0, sdb)); //blush

    o = mix(o, vec4(0), smoothstep(0.01,0.003,abs(sdh)-.01)); // head outline

    // neck
    uv = buv;
    uv.x *= 1.+.1*cos(30.*uv.y+2.);
    float sdn = sdSegment(uv, vec2(0), vec2(0,-.4))-.06;
    sdn = max(sdn, -headd);
    // neck outline
    o = mix(o, vec4(.01), smoothstep(0.01,0., sdn));
    o = mix(o, vec4(150, 122, 99,255)/255., smoothstep(0.001,0., sdn)); //neck
    headd = min(headd, sdn);

    // hair
    uv = buv;
    hair(fragCoord, uv, o, headd);

    // eyes
    /*
    if(mod(iTime, 10) < .2)
    {
        eye2(fragCoord, uv - vec2(-0.1,-.07), o);
        uv.x = -uv.x;
        eye2(fragCoord, uv - vec2(-0.1,-.07), o);
    }
    else
    {
        eye1(fragCoord, uv - vec2(-0.1,-.07), o);
        uv.x = -uv.x;
        eye1(fragCoord, uv - vec2(-0.1,-.07), o);
    }
    */
    eye1(fragCoord, uv - vec2(-0.1,-.07), o);
    uv.x = -uv.x;
    eye1(fragCoord, uv - vec2(-0.1,-.07), o);

    uv = buv;
    // nose lol
    float sd = sdSegment(uv, vec2(0,-.1), vec2(0.0,-.12));
    o = mix(o, vec4(0), smoothstep(0.003,0.,sd));

    // mouth
    uv.y += .01;
    mouth(fragCoord, uv, o);

    // body
    uv = buv;
    body(fragCoord, uv, o, headd);

    // specular highlights here n there
    uv.x = abs(uv.x);
    float sds = length(uv - vec2(0.1, -.46))-.03;
    sds = min(sds, length(uv - vec2(0.19, -.39)) + .03);
    sds = min(sds, length(uv - vec2(0.29, -.69)));
    uv = buv;
    uv.x += .02*sin(99.*uv.x);
    sds = min(sds, length(uv - vec2(0.1, .1)));
    o = mix(o, vec4(1), .05*smoothstep(0.1,0., sds));
    // smaller specular stuff
    uv = buv;
    uv.x += .016;
    sds = length(uv - vec2(0.13,-.07))-.005;
    sds = min(sds, length(uv - vec2(0.086,-.05))-.005);
    uv.x += .19;
    sds = min(sds, length(uv - vec2(0.13,-.07))-.005);
    sds = min(sds, length(uv - vec2(0.086,-.05))-.005);
    o = mix(o, vec4(1), .4*smoothstep(0.005,0., sds));
}

vec4 noise_fb_fractal(vec2 fragCoord, vec4 o)
{
    head(fragCoord, o);
    return o;
}

vec3 coolfract(vec2 fragCoord)
{
    vec2 uv = (fragCoord - .5*iResolution.xy)/iResolution.x;
    vec2 tuv = fragCoord/iResolution.xy;
    vec2 suv = uv;
    vec3 o = vec3(0,0,0);
    // 4 second loop?
    float tt = .02*iTime;
    float lu = length(uv);
    lu = mix(lu, .5/lu, 1.);
    float huv = hash1(2.1*uv + tri(2.*tt));
    uv = vec2(1.2*tri(atan(uv.y,uv.x)*2./PI-tt+.3*lu), lu);
    uv.y -= tt;
    vec2 buv = uv;
    uv.y -= 7.*tt;
    uv.y = tri(1.*uv.y);
    uv.y *= .8;

    for(float i =0.; i < 6.; i++)
    {
        uv = tri(uv)-.3;

        float inside = smoothstep(0.04,0.,(uv.x+uv.y - .3));
        inside = smoothstep(0.1,0., length(uv)-.3);
        vec3 subbed = mix(o, 1.-o, inside);
        subbed *= 1.-.1*hsv2rgb(vec3(.1*i+.6,1,1));
        o = subbed;
        o += 1./(1.+.3*length(uv-vec2(.1)));

        uv -= .2;
        uv *= rot(2.*PI*tt);
        uv *= 1.5;
    }
    o += 3./(1.+18.*length(suv));

    ///o = 2.*(o - .5);

    //o = floor(o*4.+.5*huv)/4.;
    return o;
}

// main image processing
void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    fragCoord = floor(fragCoord);
	// output final color
    fragColor.rgb = .2*coolfract(fragCoord);
    float d = length(uv - .5);
    fragColor += .8/(1.+165.*d*d*d);
    fragColor = noise_fb_fractal(fragCoord, fragColor);

    //fragColor = mix(fragColor, vec4(1,0,1,1), .7*smoothstep(0.6,0.0, what));

    fragColor = 1.14*(fragColor - .07);
    //fragColor = floor(fragColor*10.+.8*noise(uv*428. + 3533.*sin(iTime)))/10.;
    fragColor = clamp(fragColor, vec4(0), vec4(1));
}

